B.aSb=s(["A\xf1ade unas almejas los \xfaltimos 3 minutos."],t.s)
B.b85=new A.ac(B.c4,B.asA,null,"La salsa liga (se vuelve blanquecina y espesa) y la merluza est\xe1 opaca (5-6 minutos).",B.arA,B.ast,B.aSb,null,null,B.r)
B.avj=s(["Cazuelita de barro o sart\xe9n peque\xf1a"],t.s)
